fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 and that F(n-1) < 2^31, so no overflow on i32.
    let mut ret = Vec::with_capacity(n);
    // Base cases
    ret.push(0);
    ret.push(1);
    // Build up the sequence
    for i in 2..n {
        // safe to unwrap here because we know i-1 and i-2 are valid indices
        let next = ret[i - 1].wrapping_add(ret[i - 2]);
        ret.push(next);
    }
    ret
}